import { useState } from "react";
import { Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface TagInputProps {
  label: string;
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  placeholder?: string;
  description?: string;
  /** Style of the field wrapper. */
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the tag input: label, shell, tag, tagText, input or hint. The React Native counterpart of `classNames`. */
  styles?: {
    label?: StyleProp<TextStyle>;
    shell?: StyleProp<ViewStyle>;
    tag?: StyleProp<ViewStyle>;
    tagText?: StyleProp<TextStyle>;
    input?: StyleProp<TextStyle>;
    hint?: StyleProp<TextStyle>;
  };
}

export function TagInput({ label, value, defaultValue = [], onValueChange, placeholder = "Add a tag", description, style, styles: parts }: TagInputProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState(defaultValue);
  const [draft, setDraft] = useState("");
  const [focused, setFocused] = useState(false);
  const tags = value ?? internal;

  function commit(next: string[]) {
    if (value === undefined) setInternal(next);
    onValueChange?.(next);
  }

  function add() {
    const tag = draft.trim().replace(/,$/, "");
    setDraft("");
    if (tag && !tags.includes(tag)) commit([...tags, tag]);
  }

  return (
    <View style={[local.field, style]}>
      <Text style={[local.label, { color: tokens.foreground }, parts?.label]}>{label}</Text>
      <View style={[local.shell, { minHeight: metrics.controlHeight.md, borderColor: focused ? tokens.foreground : tokens.borderStrong, backgroundColor: tokens.surface }, parts?.shell]}>
        {tags.map((tag) => (
          <View key={tag} style={[local.tag, { backgroundColor: tokens.surfaceMuted, borderColor: tokens.border }, parts?.tag]}>
            <Text style={[{ color: tokens.foreground, fontSize: metrics.text.xs, fontWeight: "500" }, parts?.tagText]}>{tag}</Text>
            <Pressable accessibilityRole="button" accessibilityLabel={`Remove ${tag}`} hitSlop={8} onPress={() => commit(tags.filter((entry) => entry !== tag))}>
              <Text style={{ color: tokens.textMuted, fontSize: 14, lineHeight: 16 }}>×</Text>
            </Pressable>
          </View>
        ))}
        <TextInput
          value={draft}
          onChangeText={(text) => (text.endsWith(",") ? (setDraft(text), setTimeout(add, 0)) : setDraft(text))}
          onSubmitEditing={add}
          onKeyPress={({ nativeEvent }) => nativeEvent.key === "Backspace" && !draft && tags.length > 0 && commit(tags.slice(0, -1))}
          onFocus={() => setFocused(true)}
          onBlur={() => {
            setFocused(false);
            add();
          }}
          accessibilityLabel={label}
          placeholder={tags.length ? "" : placeholder}
          placeholderTextColor={tokens.textMuted}
          returnKeyType="done"
          blurOnSubmit={false}
          style={[local.input, { color: tokens.foreground }, parts?.input]}
        />
      </View>
      {description ? <Text style={[local.hint, { color: tokens.textMuted }, parts?.hint]}>{description}</Text> : null}
    </View>
  );
}

const local = StyleSheet.create({
  field: { alignSelf: "stretch", gap: metrics.space[2] },
  label: { fontSize: metrics.text.sm, fontWeight: "500" },
  shell: { flexDirection: "row", flexWrap: "wrap", alignItems: "center", gap: 6, padding: 6, borderWidth: 1, borderRadius: metrics.radiusControl },
  tag: { flexDirection: "row", alignItems: "center", gap: 6, paddingHorizontal: 10, paddingVertical: 4, borderWidth: 1, borderRadius: 999 },
  input: { flexGrow: 1, minWidth: 80, paddingVertical: 4, paddingHorizontal: 6, fontSize: metrics.text.sm },
  hint: { fontSize: metrics.text.xs },
});

export default TagInput;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
